291	    @Override
292	    @Transactional
293	    public void saveOwner(Owner owner) throws DataAccessException {
294	        saveOwner(owner, false);
295	    }
296	
297	    /**
298	     * Save an owner, enforcing the create-time business rules.
299	     *
300	     * <p>Duplicate rejection on create is expressed solely through the single {@code identityKey} (the
301	     * SHA-256 hex over the normalized telephone, lower-cased email and last-name Soundex, see
302	     * {@link Owner#identityKey(String, String, String)}): {@link #assertIdentityIsUnique(Owner)}
303	     * rejects an owner whose whole identity key already belongs to another owner. Because the
304	     * telephone is part of the key, two members of the same household (same last name and postcode)
305	     * with different telephones have different identity keys and are both allowed; the former separate
306	     * household-duplicate 409 no longer applies. Such an undeclared household member is created but
307	     * flagged as a possible (suspected) duplicate when its last-name Soundex and postcode match an
308	     * existing owner (see {@link #assignPossibleDuplicate(Owner, boolean)}), whereas a declared
309	     * household member ({@code sharesHousehold} set) is left unflagged; {@code sharesHousehold} now
310	     * governs only that flagging. This keeps the sole {@code POST /api/owners} duplicate rule in one
311	     * place and lets household members coexist, which the household membership-level ceiling (see
312	     * {@link #computeMembershipLevel(Owner)}) relies on to compare a new owner against the existing
313	     * members.
314	     */
315	    @Override
316	    @Transactional
317	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
318	        boolean isCreate = owner.isNew();
319	        assertEmailDomainAllowed(owner);
320	        assertIdentityIsUnique(owner);
321	        if (owner.isNew()) {
322	            assertCityHasCapacity(owner);
323	        }
324	        if (owner.getRegistrationDate() == null) {
325	            owner.setRegistrationDate(LocalDate.now());
326	        }
327	        assertRegistrationDateNotInFuture(owner);
328	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
329	        if (owner.isNew()) {
330	            assertDailyRegistrationLimit(owner);
331	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
332	            owner.setCapacityWarning(computeCapacityWarning(owner));
333	        }
334	        if (owner.isNew() && owner.getCustomerCode() == null) {
335	            owner.setCustomerCode(generateCustomerCode(owner));
336	        }
337	        if (owner.isNew() && owner.getNamesakeCount() == null) {
338	            owner.setNamesakeCount(countNamesakes(owner));
339	        }
340	        if (owner.isNew() && owner.getHouseholdCount() == null) {
341	            owner.setHouseholdCount(countHouseholdMembers(owner));
342	        }
343	        if (owner.isNew() && owner.getMembershipLevel() == null) {
344	            owner.setMembershipLevel(computeMembershipLevel(owner));
345	        }
346	        if (owner.isNew()) {
347	            assignPossibleDuplicate(owner, sharesHousehold);
348	        }
349	        ownerRepository.save(owner);
350	        if (isCreate) {
351	            String membershipNumber = Owner.membershipNumber(owner.getCustomerCode(),
352	                owner.getRegistrationDate());
353	            int membershipLevel = owner.effectiveMembershipLevel();
354	            AUDIT.info("owner created id={} customerCode={} registrationDate={} "
355	                    + "membershipLevel={} membershipNumber={}",
356	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
357	                membershipLevel, membershipNumber);
358	            OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQ.incrementAndGet(),
359	                owner.getId(), owner.primaryIdentifier(), membershipLevel);
360	            AUDIT.info(objectMapper.writeValueAsString(event));
361	        }
362	    }
363	
364	    /**
365	     * Count the existing owners that, at the moment this owner is created, share its first name
366	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
367	     * it never counts itself. This value is deterministic given the current data, so it is computed
368	     * once at creation time and stored.
369	     */
370	    private Integer countNamesakes(Owner owner) {
371	        String firstName = owner.getFirstName();
372	        String lastName = owner.getLastName();
373	        if (firstName == null || lastName == null) {
374	            return 0;
375	        }
376	        return (int) ownerRepository.findAll().stream()
377	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
378	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
379	                && lastName.equalsIgnoreCase(existing.getLastName()))
380	            .count();
381	    }
382	
383	    /**
384	     * Count the members of this owner's household at the moment it is created, i.e. the number of
385	     * owners sharing its household id (same last name and postcode, see
386	     * {@link Owner#householdId(String, String)}) plus this owner itself. An owner with no derivable
387	     * household id (missing last name or postcode) is counted as a single-member household. The value
388	     * is deterministic given the current data, so it is computed once at creation time and stored.
389	     */
390	    private Integer countHouseholdMembers(Owner owner) {
391	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
392	        if (householdId == null) {
393	            return 1;
394	        }
395	        long others = ownerRepository.findAll().stream()
396	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
397	            .filter(existing -> householdId.equals(
398	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
399	            .count();
400	        return (int) others + 1;
401	    }
402	
403	    /**
404	     * Compute a newly created owner's {@code membershipLevel} after applying the household level
405	     * ceiling, the value stored on the owner so every later read returns the capped level. The
406	     * owner's own uncapped level is first derived from its membership points (see
407	     * {@link Owner#membershipLevel(int)} and
408	     * {@link Owner#membershipPoints(Integer, String, Integer, java.time.LocalDate)}). The ceiling is
409	     * then one above the current maximum {@code membershipLevel} among the owner's existing household
410	     * members&mdash;other owners sharing its household id (same last name and postcode, see
411	     * {@link Owner#householdId(String, String)}), excluding soft-deleted owners and the owner itself.
412	     * Each level (the owner's own uncapped level and each member's) is read through
413	     * {@link Owner#effectiveMembershipLevel()}, the single resolver shared with the read-side mapping.
414	     * The returned level is the smaller of the uncapped level and that ceiling. When the owner has no
415	     * derivable household id or no existing household member, no ceiling applies and the uncapped
416	     * level is returned.
417	     */
418	    private Integer computeMembershipLevel(Owner owner) {
419	        int uncapped = owner.effectiveMembershipLevel();
420	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
421	        if (householdId == null) {
422	            return uncapped;
423	        }
424	        Integer maxHouseholdLevel = ownerRepository.findAll().stream()
425	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
426	            .filter(existing -> !existing.isDeleted())
427	            .filter(existing -> householdId.equals(
428	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
429	            .map(Owner::effectiveMembershipLevel)
430	            .max(Integer::compareTo)
431	            .orElse(null);
432	        if (maxHouseholdLevel == null) {
433	            return uncapped;
434	        }
435	        return Math.min(uncapped, maxHouseholdLevel + 1);
436	    }
437	
438	    /**
439	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
440	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
441	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
442	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
443	     * base value is deterministic in those fields and carries no sequence number (see
444	     * {@link Owner#customerCode(String, String, String)}).
445	     *
446	     * <p>When that computed code collides with an existing owner's {@code customerCode}, this appends
447	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g. a second owner
448	     * computing {@code 'NSW-1A2B3C4D'} is stored as {@code 'NSW-1A2B3C4D-2'}), so distinct owners always
449	     * receive distinct customer codes. A {@code null} computed code (missing telephone or last name) is
450	     * returned unchanged.
451	     */
452	    private String generateCustomerCode(Owner owner) {
453	        String base = Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
454	        if (base == null) {
455	            return null;
456	        }
457	        Set<String> existing = ownerRepository.findAll().stream()
458	            .filter(other -> !Objects.equals(other.getId(), owner.getId()))
459	            .map(Owner::getCustomerCode)
460	            .filter(Objects::nonNull)
461	            .collect(Collectors.toSet());
462	        if (!existing.contains(base)) {
463	            return base;
464	        }
465	        int n = 2;
466	        while (existing.contains(base + "-" + n)) {
467	            n++;
468	        }
469	        return base + "-" + n;
470	    }
471	
472	    /**
473	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
474	     * duplicate (an owner sharing this owner's whole {@code identityKey}) has already been rejected by
475	     * {@link #assertIdentityIsUnique(Owner)} before this runs. This detects the weaker overlap: an
476	     * existing owner whose identity key <em>differs</em> but whose last-name Soundex (see
477	     * {@link Owner#soundex(String)}) and postcode both match this owner. When such an owner exists,
478	     * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the matching
479	     * owner's id (the lowest id when several match); otherwise {@code possibleDuplicate} is set
480	     * {@code false} and {@code possibleDuplicateOf} left unset. In particular, two owners with the same
481	     * last name and postcode but different telephones are no longer a hard duplicate and surface here
482	     * as a soft match.
483	     *
484	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
485	     * deliberately joins an existing household, so it is left unflagged.
486	     */
487	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
488	        if (sharesHousehold) {
489	            owner.setPossibleDuplicate(false);
490	            owner.setPossibleDuplicateOf(null);
491	            return;
492	        }
493	        String identityKey = Owner.identityKey(
494	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
495	        String soundex = Owner.soundex(owner.getLastName());
496	        String postcode = owner.getPostcode();
497	        Integer match = null;
498	        if (soundex != null && !soundex.isEmpty() && postcode != null) {
499	            match = ownerRepository.findAll().stream()
500	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
501	                .filter(existing -> !existing.isDeleted())
502	                .filter(existing -> !identityKey.equals(Owner.identityKey(
503	                    existing.getTelephone(), existing.getEmail(), existing.getLastName())))
504	                .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName())))
505	                .filter(existing -> postcode.equals(existing.getPostcode()))
506	                .map(Owner::getId)
507	                .filter(Objects::nonNull)
508	                .min(Integer::compareTo)
509	                .orElse(null);
510	        }
511	        owner.setPossibleDuplicate(match != null);
512	        owner.setPossibleDuplicateOf(match);
513	    }
514	
515	    /**
516	     * Enforce that the owner's email domain is not on the disposable-domain blocklist, throwing
517	     * {@link DisposableEmailDomainException} when it is. The blocklist check is the single source
518	     * of truth in {@link Owner#isDisposableEmailDomain(String)}; an owner with no email places no
519	     * constraint.
520	     */
521	    private void assertEmailDomainAllowed(Owner owner) {
522	        if (Owner.isDisposableEmailDomain(owner.getEmail())) {
523	            throw new DisposableEmailDomainException(owner.getEmail());
524	        }
525	    }
526	
527	    /**
528	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
529	     * {@link DuplicateIdentityException} if one does. Duplicate detection is now the single
530	     * {@code identityKey}: the SHA-256 hex over the normalized telephone, lower-cased email and the
531	     * Soundex of the last name (see {@link Owner#identityKey(String, String, String)}). Two owners
532	     * are a hard duplicate exactly when their whole identity keys are equal.
533	     *
534	     * <p>Because the telephone is part of the key, two members of the same household (same last name
535	     * and postcode) with different telephones have different identity keys and are both allowed —
536	     * they surface instead as a soft match (see {@link #assignPossibleDuplicate(Owner, boolean)}).
537	     * The email-domain blocklist is applied first (see {@link #assertEmailDomainAllowed(Owner)}), and
538	     * soft-deleted owners are ignored. The owner being saved is excluded by id so updating an owner in
539	     * place never conflicts with itself.
540	     */
541	    private void assertIdentityIsUnique(Owner owner) {
542	        String identityKey = Owner.identityKey(
543	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
544	        boolean duplicate = ownerRepository.findAll().stream()
545	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
546	            .filter(existing -> !existing.isDeleted())
547	            .map(existing -> Owner.identityKey(
548	                existing.getTelephone(), existing.getEmail(), existing.getLastName()))
549	            .anyMatch(identityKey::equals);
550	        if (duplicate) {
551	            throw new DuplicateIdentityException(identityKey);
552	        }
553	    }
554	
555	    /**
556	     * Enforce that the owner's city has not yet reached its capacity, throwing
557	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
558	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
559	     */
560	    private void assertCityHasCapacity(Owner owner) {
561	        String city = owner.getCity();
562	        if (city == null) {
563	            return;
564	        }
565	        long count = ownerRepository.findAll().stream()
566	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
567	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
568	            .count();
569	        if (count >= MAX_OWNERS_PER_CITY) {
570	            throw new CityAtCapacityException(city);
571	        }
572	    }
573	
574	    /**
575	     * Enforce that the owner's registration date is not later than the current server date, throwing
576	     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
577	     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
578	     * harmless no-op for that case.
579	     */
580	    private void assertRegistrationDateNotInFuture(Owner owner) {
581	        LocalDate registrationDate = owner.getRegistrationDate();
582	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
583	            throw new FutureRegistrationDateException(registrationDate);
584	        }
585	    }
586	
587	    /**
588	     * Roll a registration date forward to the next business day. A date that falls on a Saturday,
589	     * Sunday or a listed public holiday is advanced to the following non-holiday weekday; a plain
590	     * weekday is returned unchanged. This is applied to the effective registration date (whether
591	     * supplied in the request or defaulted to the server date) so that every value derived from
592	     * it&mdash;such as the membership number's year segment and the daily create-limit
593	     * counting&mdash;uses the adjusted business day.
594	     */
595	    private static LocalDate rollToBusinessDay(LocalDate date) {
596	        if (date == null) {
597	            return null;
598	        }
599	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
600	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
601	                || PUBLIC_HOLIDAYS.contains(date)) {
602	            date = date.plusDays(1);
603	        }
604	        return date;
605	    }
606	
607	    /**
608	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
609	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
610	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
611	     * is excluded by id.
612	     */
613	    private void assertDailyRegistrationLimit(Owner owner) {
614	        LocalDate registrationDate = owner.getRegistrationDate();
615	        if (registrationDate == null) {
616	            return;
617	        }
618	        long count = ownerRepository.findAll().stream()
619	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
620	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
621	            .count();
622	        if (count >= MAX_OWNERS_PER_DAY) {
623	            throw new DailyRegistrationLimitException(registrationDate);
624	        }
625	    }
626	
627	    /**
628	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
629	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
630	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
631	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
632	     * stored on the owner.
633	     */
634	    private boolean computeBulkSignupWarning(Owner owner) {
635	        LocalDate registrationDate = owner.getRegistrationDate();
636	        if (registrationDate == null) {
637	            return false;
638	        }
639	        long count = ownerRepository.findAll().stream()
640	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
641	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
642	            .count();
643	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
644	    }
645	
646	    /**
647	     * Compute whether a newly created owner should carry a capacity warning, i.e. whether its city
648	     * (compared case-insensitively) already contains at least {@link #CAPACITY_WARNING_THRESHOLD} but
649	     * fewer than {@link #MAX_OWNERS_PER_CITY} owners, signalling the city is approaching its hard
650	     * capacity limit. The owner being saved is excluded by id, mirroring the counting done by
651	     * {@link #assertCityHasCapacity(Owner)}. A city with no name never warns. Like the city-capacity
652	     * rule this reflects the state at creation time, so it is computed once and stored on the owner.
653	     */
654	    private boolean computeCapacityWarning(Owner owner) {
655	        String city = owner.getCity();
656	        if (city == null) {
657	            return false;
658	        }
659	        long count = ownerRepository.findAll().stream()
660	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
661	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
662	            .count();
663	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
664	    }
665	
666	    @Override
667	    @Transactional(readOnly = true)
668	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
669	        return ownerRepository.findByLastName(lastName);
670	    }
671	
672	    @Override
673	    @Transactional(readOnly = true)
674	    public Collection<Visit> findVisitsByPetId(int petId) {
675	        return visitRepository.findByPetId(petId);
676	    }
677	
678	    @Override
679	    @Transactional(readOnly = true)
680	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
681	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
682	    }
683	
684	    private <T> T findEntityById(Supplier<T> supplier) {
685	        try {
686	            return supplier.get();
687	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
688	            // Just ignore not found exceptions for Jdbc/Jpa realization
689	            return null;
690	        }
691	    }
692	
693	}
