305	    }
306	
307	    /**
308	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
309	     * source of truth for how an email is persisted, so inputs that differ only in letter case
310	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
311	     * (create and update, mapper or hand-copied) stores the same canonical value.
312	     *
313	     * @param email the raw email, possibly {@code null}
314	     * @return the lower-cased form, or {@code null} if the input was {@code null}
315	     */
316	    public static String normalizeEmail(String email) {
317	        return email == null ? null : email.toLowerCase();
318	    }
319	
320	    /**
321	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
322	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
323	     */
324	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
325	        "mailinator.com",
326	        "tempmail.com",
327	        "guerrillamail.com");
328	
329	    /**
330	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
331	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
332	     * This is the single source of truth for which email domains are rejected, shared by any
333	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
334	     *
335	     * @param email the owner's email, possibly {@code null}
336	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
337	     */
338	    public static boolean isDisposableEmailDomain(String email) {
339	        if (email == null) {
340	            return false;
341	        }
342	        int at = email.lastIndexOf('@');
343	        if (at < 0) {
344	            return false;
345	        }
346	        String domain = email.substring(at + 1).toLowerCase();
347	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
348	    }
349	
350	    /**
351	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
352	     * truth for how a telephone is compared and persisted, so inputs that differ only in
353	     * formatting (spaces, dashes, brackets) are treated as the same number.
354	     *
355	     * <p>The rules are:
356	     * <ul>
357	     *   <li>spaces, dashes and brackets are stripped;</li>
358	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
359	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
360	     *       is dropped from the national digits;</li>
361	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
362	     *   <li>for a recognized country code the national number (the digits after the country
363	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
364	     *       digits and {@code '+1'} requires 10.</li>
365	     * </ul>
366	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
367	     * values are returned unchanged.
368	     *
369	     * @param telephone the raw telephone, possibly {@code null}
370	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
371	     *     valid E.164 number
372	     */
373	    public static String normalizeTelephone(String telephone) {
374	        if (telephone == null) {
375	            return null;
376	        }
377	        String trimmed = telephone.trim();
378	        boolean hasCountryCode = trimmed.startsWith("+");
379	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
380	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
381	        if (hasCountryCode) {
382	            stripped = stripped.substring(1);
383	        }
384	        if (!stripped.matches("\\d+")) {
385	            return null;
386	        }
387	        String digits;
388	        if (hasCountryCode) {
389	            digits = stripped;
390	        } else {
391	            if (stripped.startsWith("0")) {
392	                stripped = stripped.substring(1);
393	            }
394	            digits = "61" + stripped;
395	        }
396	        if (digits.length() < 8 || digits.length() > 15) {
397	            return null;
398	        }
399	        if (!hasValidNationalNumberLength(digits)) {
400	            return null;
401	        }
402	        return "+" + digits;
403	    }
404	
405	    /**
406	     * Format a stored E.164 telephone for human display: the country code, a space, then the
407	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
408	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
409	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
410	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
411	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
412	     * kept unchanged elsewhere.
413	     *
414	     * @param telephone the stored E.164 telephone, possibly {@code null}
415	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
416	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
417	     *     unchanged
418	     */
419	    public static String telephoneDisplay(String telephone) {
420	        if (telephone == null) {
421	            return null;
422	        }
423	        if (!telephone.matches("\\+\\d+")) {
424	            return telephone;
425	        }
426	        String digits = telephone.substring(1);
427	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
428	            if (digits.startsWith(countryCode)) {
429	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
430	            }
431	        }
432	        return "+" + groupDigits(digits);
433	    }
434	
435	    /**
436	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
437	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
438	     * {@code "412345678"} becomes {@code "412 345 678"}).
439	     *
440	     * @param digits the national digits
441	     * @return the space-grouped digits
442	     */
443	    private static String groupDigits(String digits) {
444	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
445	        for (int i = 0; i < digits.length(); i++) {
446	            if (i > 0 && i % 3 == 0) {
447	                grouped.append(' ');
448	            }
449	            grouped.append(digits.charAt(i));
450	        }
451	        return grouped.toString();
452	    }
453	
454	    /**
455	     * Required national-number length (the count of digits after the country code) for each
456	     * recognized country code, longest country code first so the prefix match is unambiguous.
457	     */
458	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
459	    static {
460	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
461	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
462	    }
463	
464	    /**
465	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
466	     * length its country code requires. A country code with no registered length places no
467	     * additional constraint and is accepted.
468	     *
469	     * @param digits the E.164 digits without the leading {@code '+'}
470	     * @return {@code true} if the national-number length is valid for the country code
471	     */
472	    private static boolean hasValidNationalNumberLength(String digits) {
473	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
474	            String countryCode = entry.getKey();
475	            if (digits.startsWith(countryCode)) {
476	                return digits.length() - countryCode.length() == entry.getValue();
477	            }
478	        }
479	        return true;
480	    }
481	
482	    /**
483	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
484	     * upper-cased abbreviation.
485	     */
486	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
487	        "ST", "STREET",
488	        "RD", "ROAD",
489	        "AVE", "AVENUE");
490	
491	    /**
492	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
493	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
494	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
495	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
496	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
497	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
498	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
499	     * value. The transform is idempotent: a normalized address normalizes to itself.
500	     *
501	     * @param address the raw address, possibly {@code null}
502	     * @return the normalized form, or {@code null} if the input was {@code null}
503	     */
504	    public static String normalizeAddress(String address) {
505	        if (address == null) {
506	            return null;
507	        }
508	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
509	        if (collapsed.isEmpty()) {
510	            return collapsed;
511	        }
512	        String[] tokens = collapsed.split(" ");
513	        StringBuilder normalized = new StringBuilder(collapsed.length());
514	        for (int i = 0; i < tokens.length; i++) {
515	            if (i > 0) {
516	                normalized.append(' ');
517	            }
518	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
519	        }
520	        return normalized.toString();
521	    }
