523	    /**
524	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
525	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
526	     * result is that line, with a single space and {@code addressLine2} appended when the second line
527	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
528	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
529	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
530	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
531	     *
532	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
533	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
534	     * @param flatAddress the normalized flat address, possibly {@code null}
535	     * @return the composed address, or the flat value / {@code null} when no structured line is present
536	     */
537	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
538	        if (isPresent(addressLine1)) {
539	            if (isPresent(addressLine2)) {
540	                return addressLine1 + " " + addressLine2;
541	            }
542	            return addressLine1;
543	        }
544	        return flatAddress;
