572	    /**
573	     * Normalize a household field (such as last name or address) to its canonical form for
574	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
575	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
576	     * that differ only in letter case or spacing are treated as the same value.
577	     *
578	     * @param value the raw field value, possibly {@code null}
579	     * @return the normalized form, or {@code null} if the input was {@code null}
580	     */
581	    public static String normalizeHousehold(String value) {
582	        if (value == null) {
583	            return null;
584	        }
585	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
