588	    /**
589	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
590	     * last name (compared case-insensitively with collapsed whitespace, see
591	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
592	     * those two fields, so two owners who share a last name and postcode are assigned the same id
593	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
594	     * upper-cased hex characters of the SHA-256 digest of
595	     * {@code normalizedLastName + '|' + postcode}.
596	     *
597	     * @param lastName the owner's last name, possibly {@code null}
598	     * @param postcode the owner's postcode, possibly {@code null}
599	     * @return the household id, or {@code null} if either field is {@code null}
600	     */
601	    public static String householdId(String lastName, String postcode) {
602	        String normalizedLastName = normalizeHousehold(lastName);
603	        if (normalizedLastName == null || postcode == null) {
604	            return null;
605	        }
606	        String key = normalizedLastName + "|" + postcode;
607	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
608	    }
