610	    /**
611	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
612	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
613	     * so they all agree on algorithm and encoding.
614	     *
615	     * @param value the string to digest, never {@code null}
616	     * @return the 64-character lower-case hex digest
617	     */
618	    private static String sha256Hex(String value) {
619	        try {
620	            byte[] digest = MessageDigest.getInstance("SHA-256")
621	                .digest(value.getBytes(StandardCharsets.UTF_8));
622	            StringBuilder hex = new StringBuilder(digest.length * 2);
623	            for (byte b : digest) {
624	                hex.append(String.format("%02x", b));
625	            }
626	            return hex.toString();
627	        } catch (NoSuchAlgorithmException e) {
628	            // SHA-256 is a standard algorithm required to be present on every JVM.
629	            throw new IllegalStateException("SHA-256 not available", e);
630	        }
631	    }
