633	    /**
634	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
635	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
636	     * <ul>
637	     *   <li>{@code REGION} is the region code derived from the postcode (see
638	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
639	     *       in no known range, and</li>
640	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
641	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
642	     *       name.</li>
643	     * </ul>
644	     * The value is deterministic in the postcode, telephone and last name (e.g.
645	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
646	     *
647	     * @param postcode the owner's postcode, possibly {@code null}
648	     * @param telephone the owner's raw telephone, possibly {@code null}
649	     * @param lastName the owner's last name, possibly {@code null}
650	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
651	     */
652	    public static String customerCode(String postcode, String telephone, String lastName) {
653	        if (telephone == null || lastName == null) {
654	            return null;
655	        }
656	        String region = regionForPostcode(postcode);
657	        if (region == null) {
658	            region = "UNKNOWN";
659	        }
660	        String normalizedTelephone = normalizeTelephone(telephone);
661	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
662	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
663	    }
