665	    /**
666	     * Compute an owner's {@code identityKey}, the single derived value through which all
667	     * duplicate detection is now expressed. It is the lower-case hex SHA-256 digest (see
668	     * {@link #sha256Hex(String)}) of the three identity components joined with {@code '|'}:
669	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where
670	     * <ul>
671	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
672	     *   <li>the lower-cased email (see {@link #normalizeEmail(String)}), or the empty string
673	     *       when no email is present, and</li>
674	     *   <li>the Soundex code of the last name (see {@link #soundex(String)}).</li>
675	     * </ul>
676	     * A {@code null} component is rendered as the empty string before hashing. Two owners are the
677	     * same identity only when their <em>whole</em> keys are equal; because the telephone is part of
678	     * the key, two members of the same household (same last name and postcode) with different
679	     * telephones have different keys and are not a hard duplicate.
680	     *
681	     * @param telephone the owner's raw telephone, possibly {@code null}
682	     * @param email the owner's email, possibly {@code null}
683	     * @param lastName the owner's last name, possibly {@code null}
684	     * @return the 64-character lower-case hex identity key, never {@code null}
685	     */
686	    public static String identityKey(String telephone, String email, String lastName) {
687	        String normalizedTelephone = normalizeTelephone(telephone);
688	        String normalizedEmail = normalizeEmail(email);
689	        String lastNameSoundex = soundex(lastName);
690	        String raw = (normalizedTelephone == null ? "" : normalizedTelephone)
691	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
692	            + "|" + (lastNameSoundex == null ? "" : lastNameSoundex);
693	        return sha256Hex(raw);
694	    }
