696	    /** Soundex digit for each consonant; vowels, {@code H}, {@code W} and {@code Y} map to '0'. */
697	    private static final Map<Character, Character> SOUNDEX_CODES = new HashMap<>();
698	    static {
699	        for (char c : "BFPV".toCharArray()) {
700	            SOUNDEX_CODES.put(c, '1');
701	        }
702	        for (char c : "CGJKQSXZ".toCharArray()) {
703	            SOUNDEX_CODES.put(c, '2');
704	        }
705	        for (char c : "DT".toCharArray()) {
706	            SOUNDEX_CODES.put(c, '3');
707	        }
708	        SOUNDEX_CODES.put('L', '4');
709	        for (char c : "MN".toCharArray()) {
710	            SOUNDEX_CODES.put(c, '5');
711	        }
712	        SOUNDEX_CODES.put('R', '6');
713	    }
714	
715	    /**
716	     * Compute the American Soundex code of a name: the upper-cased first letter followed by three
717	     * digits encoding the following consonants ({@code B,F,P,V}->1; {@code C,G,J,K,Q,S,X,Z}->2;
718	     * {@code D,T}->3; {@code L}->4; {@code M,N}->5; {@code R}->6), padded with zeros to length four.
719	     * Vowels ({@code A,E,I,O,U,Y}) separate codes; {@code H} and {@code W} are ignored so two
720	     * like-coded consonants on either side of them collapse to a single digit; adjacent letters with
721	     * the same code also collapse to one. Non-letters are stripped before coding. This is the single
722	     * source of truth for the surname component of the {@code identityKey} and the soft-match rule.
723	     *
724	     * @param name the raw name, possibly {@code null}
725	     * @return the four-character Soundex code, {@code null} if the input is {@code null}, or the empty
726	     *     string if the input contains no letters
727	     */
728	    public static String soundex(String name) {
729	        if (name == null) {
730	            return null;
731	        }
732	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
733	        if (letters.isEmpty()) {
734	            return "";
735	        }
736	        StringBuilder code = new StringBuilder();
737	        code.append(letters.charAt(0));
738	        char previous = SOUNDEX_CODES.getOrDefault(letters.charAt(0), '0');
739	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
740	            char c = letters.charAt(i);
741	            if (c == 'H' || c == 'W') {
742	                continue;
743	            }
744	            char digit = SOUNDEX_CODES.getOrDefault(c, '0');
745	            if (digit != '0' && digit != previous) {
746	                code.append(digit);
747	            }
748	            previous = digit;
749	        }
750	        while (code.length() < 4) {
751	            code.append('0');
752	        }
753	        return code.toString();
754	    }
