775	    /**
776	     * Compute an owner's {@code fiscalYear}, the fiscal year of a date formatted {@code 'FY<YY>'}
777	     * where {@code YY} is the last two digits of the fiscal-year number (see
778	     * {@link #fiscalYearNumber(LocalDate)}). The fiscal year starts on 1 July, so a date of
779	     * {@code 2026-08-01} yields {@code 'FY27'} and {@code 2026-03-01} yields {@code 'FY26'}.
780	     *
781	     * @param date the date to derive the fiscal year from, possibly {@code null}
782	     * @return the fiscal year, or {@code null} if {@code date} is {@code null}
783	     */
784	    public static String fiscalYear(LocalDate date) {
785	        if (date == null) {
786	            return null;
787	        }
788	        return String.format("FY%02d", fiscalYearNumber(date) % 100);
