809	    /**
810	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
811	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
812	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
813	     * and gains 3 when the owner's tenure is more than one fiscal year (the tenure being the number
814	     * of elapsed fiscal years from {@code registrationDate} to today, see
815	     * {@link #fiscalYear(LocalDate)}). Because a newly created owner has zero tenure, the tenure
816	     * points accrue only once the owner has been a member for more than a full fiscal year.
817	     *
818	     * @param namesakeCount the owner's namesake count, possibly {@code null}
819	     * @param email the owner's email, possibly {@code null}
820	     * @param householdCount the number of members in the owner's household, possibly {@code null}
821	     * @param registrationDate the owner's registration date, possibly {@code null}
822	     * @return the membership points, a non-negative integer
823	     */
824	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
825	            LocalDate registrationDate) {
826	        int points = 0;
827	        if (email != null && !email.isEmpty()) {
828	            points += 2;
829	        }
830	        if (namesakeCount != null && namesakeCount == 0) {
831	            points += 1;
832	        }
833	        if (householdCount != null && householdCount >= 3) {
834	            points += 2;
835	        }
836	        if (registrationDate != null
837	            && fiscalYearNumber(LocalDate.now()) - fiscalYearNumber(registrationDate) > 1) {
838	            points += 3;
839	        }
840	        return points;
841	    }
