843	    /**
844	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
845	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
846	     *
847	     * @param membershipPoints the owner's membership points
848	     * @return the membership level, an integer from 1 to 4
849	     */
850	    public static int membershipLevel(int membershipPoints) {
851	        if (membershipPoints >= 6) {
852	            return 4;
853	        }
854	        if (membershipPoints >= 4) {
855	            return 3;
856	        }
857	        if (membershipPoints >= 2) {
858	            return 2;
859	        }
860	        return 1;
861	    }
