970	    /**
971	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
972	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
973	     * inclusive low and high bound of the region's valid 4-digit postcodes
974	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
975	     * table (including {@code 'UNKNOWN'}) places no range constraint.
976	     */
977	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
978	        "NSW", new int[] {2000, 2099},
979	        "VIC", new int[] {3000, 3099},
980	        "QLD", new int[] {4000, 4099});
