982	    /**
983	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
984	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
985	     * digits, or one that falls in no known range resolves to {@code null}.
986	     *
987	     * @param postcode the owner's postcode, possibly {@code null}
988	     * @return the matching region, or {@code null} when no range contains the postcode
989	     */
990	    private static String regionForPostcode(String postcode) {
991	        if (postcode == null || !postcode.matches("\\d{4}")) {
992	            return null;
993	        }
994	        int value = Integer.parseInt(postcode);
995	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
996	            int[] range = entry.getValue();
997	            if (value >= range[0] && value <= range[1]) {
998	                return entry.getKey();
999	            }
1000	        }
1001	        return null;
1002	    }
1003	
1004	    /**
1005	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
1006	     * {@code null} or empty postcode is always valid. When present it must be exactly four
1007	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
1008	     * range the value must fall within that inclusive range. A city with no known region accepts
1009	     * any four-digit postcode. This is the single source of
1010	     * truth for postcode validity, shared by the DTO validation and any persistence path.
1011	     *
1012	     * @param postcode the owner's postcode, possibly {@code null}
1013	     * @param city the owner's city, possibly {@code null}
1014	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
1015	     */
1016	    public static boolean isPostcodeValidForCity(String postcode, String city) {
1017	        if (postcode == null || postcode.isEmpty()) {
1018	            return true;
1019	        }
1020	        if (!postcode.matches("\\d{4}")) {
1021	            return false;
1022	        }
1023	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
1024	        if (range == null) {
1025	            return true;
1026	        }
1027	        int value = Integer.parseInt(postcode);
1028	        return value >= range[0] && value <= range[1];
1029	    }
1030	
1031	    /**
1032	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
1033	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
1034	     * value is deterministic in the customer code and is the standard Luhn check digit: each
1035	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
1036	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
1037	     * brings the weighted sum up to the next multiple of ten.
1038	     *
1039	     * @param customerCode the owner's customer code, possibly {@code null}
1040	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
1041	     */
1042	    public static Integer checkDigit(String customerCode) {
1043	        if (customerCode == null) {
1044	            return null;
1045	        }
1046	        int sum = 0;
1047	        boolean dbl = true;
1048	        for (int i = customerCode.length() - 1; i >= 0; i--) {
1049	            char c = customerCode.charAt(i);
1050	            if (c < '0' || c > '9') {
1051	                continue;
1052	            }
1053	            int d = c - '0';
1054	            if (dbl) {
1055	                d *= 2;
1056	                if (d > 9) {
1057	                    d -= 9;
1058	                }
1059	            }
1060	            sum += d;
1061	            dbl = !dbl;
1062	        }
1063	        return (10 - (sum % 10)) % 10;
1064	    }
1065	
1066	    /**
1067	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
1068	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
1069	     * is deterministic in the email.
1070	     *
1071	     * @param email the owner's email, possibly {@code null}
1072	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
1073	     */
1074	    public static String contactPreference(String email) {
1075	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
1076	    }
1077	
1078	    /**
1079	     * Compose an owner's {@code salutation} from the optional honorific title and the last name.
1080	     * When a title is present the result is the title and the last name separated by a single space
1081	     * (e.g. {@code 'DR Franklin'}); when no title is given the result is just the last name. The
1082	     * value is deterministic in those two fields.
1083	     *
1084	     * @param title the owner's honorific title, possibly {@code null} or blank
1085	     * @param lastName the owner's last name, possibly {@code null}
1086	     * @return the composed salutation
1087	     */
1088	    public static String salutation(String title, String lastName) {
1089	        if (title == null || title.isBlank()) {
1090	            return lastName;
1091	        }
1092	        return title + " " + lastName;
1093	    }
1094	
1095	    /**
1096	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
1097	     * date. The age in whole years is the number of completed years between {@code birthDate} and
1098	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
1099	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
1100	     * two fields and is only defined when both are present.
1101	     *
1102	     * @param birthDate the owner's date of birth, possibly {@code null}
1103	     * @param registrationDate the owner's registration date, possibly {@code null}
1104	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
1105	     *     is {@code null}
1106	     */
1107	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
1108	        if (birthDate == null || registrationDate == null) {
1109	            return null;
1110	        }
1111	        int age = Period.between(birthDate, registrationDate).getYears();
1112	        if (age < 18) {
1113	            return "MINOR";
1114	        }
1115	        if (age < 65) {
1116	            return "ADULT";
1117	        }
1118	        return "SENIOR";
1119	    }
1120	
1121	    protected Set<Pet> getPetsInternal() {
1122	        if (this.pets == null) {
1123	            this.pets = new HashSet<>();
1124	        }
1125	        return this.pets;
1126	    }
1127	
