1133	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
1134	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
1135	        return Collections.unmodifiableList(sortedPets);
